import logging
from logging.handlers import SMTPHandler

from ute_ue.robot_api.robot_utils import get_robot_variable


class MailSender:
    """Class responsible for sending email notifications"""
    MAIL_HOST = 'mailrelay.int.nokia.com'
    FROM_ADDR = 'I_UTE_UE@internal.nsn.com'
    SEND_TO_ADDR = ['bartosz.koperek@nokia.com']

    def __init__(self):
        """Initialize mail logger"""
        suite_path = get_robot_variable('SUITE SOURCE')
        self.message = [f'Test Suite path: {suite_path}']
        self.logger = logging.getLogger(name='mail_log')
        self.logger.setLevel(level=logging.DEBUG)
        file_handler = logging.handlers.RotatingFileHandler('notifications.log')
        file_handler.setLevel(level=logging.DEBUG)
        self.logger.addHandler(file_handler)
        self.mail_handler = SMTPHandler(mailhost=self.MAIL_HOST,
                                        fromaddr=self.FROM_ADDR,
                                        toaddrs=self.SEND_TO_ADDR,
                                        subject='taf monitoring report')
        self.mail_handler.setLevel(level=logging.DEBUG)
        self.mail_handler.setFormatter(logging.Formatter(fmt="%(message)s",
                                                         datefmt="%Y-%m-%d %H:%M:%S"))

    def update_message(self, info):
        """Update notification message with new line"""
        self.message.append(info)

    def send_mail(self):
        """Send e-mail with a message passed in the msg parameter"""
        msg = "\n".join(self.message)
        try:
            self.logger.addHandler(hdlr=self.mail_handler)
            self.logger.debug(msg=msg)
            self.logger.removeHandler(hdlr=self.mail_handler)
        except Exception as exp:
            self.logger.debug(msg=f'Exception: {str(exp)}')
